{
  "code": "import { DatabaseSync } from 'node:sqlite';

interface DocumentRow {
  id: number;
  title: string;
  content: string;
  metadata: string;
  created_at: Date;
}

const db = new DatabaseSync(':memory:');
db.exec(`
  CREATE TABLE documents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    metadata TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`);

export const db = db;

export function insertDocument(title: string, content: string, metadata: string): void {
  const stmt = db.prepare(
    'INSERT INTO documents (title, content, metadata) VALUES (?, ?, ?)' 
  );
  stmt.run(title, content, metadata);
}

export function getDocumentById(id: number): DocumentRow | undefined {
  const stmt = db.prepare('SELECT * FROM documents WHERE id = ?');
  const result = stmt.get(id) as unknown as DocumentRow | undefined;
  return result;
}

export function getAllDocuments(): DocumentRow[] {
  const stmt = db.prepare('SELECT * FROM documents');
  const results = stmt.all() as unknown as DocumentRow[];
  return results;
}
"
}

{
  "code": "import { Router, type Request, type Response } from "express";
import { db, insertDocument, getDocumentById, getAllDocuments } from "../db/documents-table";

interface DocumentRow {
  id: number;
  title: string;
  content: string;
  metadata: string;
}

type OcrResult = {
  text: string;
};

type ScanResult = {
  pages: number;
};

const router = Router();

// Mock OCR function for demonstration purposes
function ocr(imageData: Buffer): OcrResult {
  return { text: "Mock OCR result" };
}

// Mock scan function for demonstration purposes
function scan(documentFile: Buffer): ScanResult {
  return { pages: 1 };
}

router.post("/upload", async (req: Request, res: Response) => {
  if (!req.files || !req.files.document) {
    return res.status(400).send("No document file provided");
  }

  const documentFile = req.files.document as Express.Multer.File;
  const scanResult = scan(documentFile.buffer);
  const ocrResult = ocr(documentFile.buffer);

  const title = req.body.title || "Untitled Document";
  const metadata = JSON.stringify({ pages: scanResult.pages });

  insertDocument(title, ocrResult.text, metadata);

  res.status(201).send("Document processed and indexed");
});

router.get("/documents", (req: Request, res: Response) => {
  const documents = getAllDocuments();
  res.json(documents);
});

router.get("/documents/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const document = getDocumentById(id);

  if (!document) {
    return res.status(404).send("Document not found");
  }

  res.json(document);
});

export const router = router;"
}

{
  "code": "import type { Request, Response, NextFunction } from "express";

const validUser = {
  username: "admin",
  password: "password"
};

export function middleware(req: Request, res: Response, next: NextFunction): void {
  if (req.method !== 'POST' || req.path !== '/login') {
    next();
    return;
  }

  const { username, password } = req.body;

  if (username === validUser.username && password === validUser.password) {
    req.session.isAuthenticated = true;
    next();
  } else {
    res.status(401).send('Unauthorized');
  }
}"
}

{
  "code": "import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is intended to support MFA and social login via django-allauth.
  // Since the purpose does not specify protecting every request, we will only handle
  // requests that are relevant to MFA or social login.

  // For demonstration purposes, let's assume that MFA and social login are handled
  // through specific endpoints or routes. We'll check the request path and method
  // to determine if this middleware should process the request.

  const mfaRoutes = ['/mfa/verify', '/mfa/setup'];
  const socialLoginRoutes = ['/social/login', '/social/callback'];

  if (!mfaRoutes.includes(req.path) && !socialLoginRoutes.includes(req.path)) {
    // If the request is not related to MFA or social login, pass it along.
    next();
    return;
  }

  // If the request is related to MFA or social login, perform the necessary checks.
  // For example, you might verify a token, check for session data, etc.

  // Placeholder logic for demonstration purposes.
  if (req.method === 'POST') {
    // Example: Verify a token for MFA setup.
    const token = req.body.token;
    if (!token) {
      res.status(400).send('Token is required for MFA setup.');
      return;
    }

    // Assume token verification logic here.
    // If token is valid, proceed to the next middleware or route handler.
    next();
  } else {
    // For other methods or routes, simply pass the request along.
    next();
  }
}"
}

