  "code": "import { DatabaseSync } from 'node:sqlite';

interface AnalyticsEvent {
  id: number;
  event_type: string;
  timestamp: Date;
  user_id: number | null;
  session_id: string;
  page_url: string;
  referrer: string;
}

const db = new DatabaseSync(':memory:');
db.exec(`
  CREATE TABLE analytics_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_type TEXT NOT NULL,
    timestamp DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    user_id INTEGER,
    session_id TEXT NOT NULL,
    page_url TEXT NOT NULL,
    referrer TEXT
  );
`);

export const db;

export function insertAnalyticsEvent(event: Omit<AnalyticsEvent, 'id'>): void {
  const stmt = db.prepare(
    `INSERT INTO analytics_events (event_type, user_id, session_id, page_url, referrer)
     VALUES (?, ?, ?, ?, ?)`
  );
  stmt.run(
    event.event_type,
    event.user_id,
    event.session_id,
    event.page_url,
    event.referrer
  );
}

export function getAnalyticsEvents(): AnalyticsEvent[] {
  const stmt = db.prepare('SELECT * FROM analytics_events');
  return stmt.all() as unknown as AnalyticsEvent[];
}

export function getAnalyticsEventById(id: number): AnalyticsEvent | undefined {
  const stmt = db.prepare('SELECT * FROM analytics_events WHERE id = ?');
  return stmt.get([id]) as unknown as AnalyticsEvent | undefined;
}"
}

