  "code": "import { DatabaseSync } from "node:sqlite";

interface AnalyticsEvent {
  id: number;
  event_type: string;
  timestamp: Date;
  user_id: string | null;
  session_id: string;
}

const db = new DatabaseSync(':memory:');
db.exec(`
  CREATE TABLE IF NOT EXISTS analytics_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_type TEXT NOT NULL,
    timestamp DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    user_id TEXT,
    session_id TEXT NOT NULL
  );
`);

export const db;

export function insertAnalyticsEvent(event: Omit<AnalyticsEvent, 'id'>): void {
  const stmt = db.prepare(
    `INSERT INTO analytics_events (event_type, user_id, session_id) VALUES (?, ?, ?)`
  );
  stmt.run(event.event_type, event.user_id, event.session_id);
}

export function getAnalyticsEventById(id: number): AnalyticsEvent | undefined {
  const stmt = db.prepare(`SELECT * FROM analytics_events WHERE id = ?`);
  const result = stmt.get([id]) as unknown as Record<string, any> | undefined;
  return result ? { ...result, timestamp: new Date(result.timestamp) } : undefined;
}

export function getAllAnalyticsEvents(): AnalyticsEvent[] {
  const stmt = db.prepare(`SELECT * FROM analytics_events`);
  const results = stmt.all() as unknown as Record<string, any>[];
  return results.map(row => ({ ...row, timestamp: new Date(row.timestamp) }));
}"
}

