  "code": "import { DatabaseSync } from "node:sqlite";

interface AnalyticsEvent {
  id: number;
  event_type: string;
  user_id: number;
  session_id: number;
  timestamp: Date;
}

const db = new DatabaseSync(':memory:');
db.exec(`
  CREATE TABLE analytics_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_type TEXT NOT NULL,
    user_id INTEGER NOT NULL,
    session_id INTEGER NOT NULL,
    timestamp DATETIME NOT NULL
  );
`);

export const dbInstance = db;

export function insertEvent(event: Omit<AnalyticsEvent, 'id' | 'timestamp'>): void {
  const stmt = db.prepare(
    `INSERT INTO analytics_events (event_type, user_id, session_id, timestamp) VALUES (?, ?, ?, datetime('now'))`
  );
  stmt.run(event.event_type, event.user_id, event.session_id);
}

export function getEventById(id: number): AnalyticsEvent | undefined {
  const stmt = db.prepare(`SELECT * FROM analytics_events WHERE id = ?`);
  const result = stmt.get([id]) as unknown as Record<string, any> | undefined;
  return result
    ? {
        ...result,
        timestamp: new Date(result.timestamp)
      }
    : undefined;
}

export function getAllEvents(): AnalyticsEvent[] {
  const stmt = db.prepare(`SELECT * FROM analytics_events`);
  const results = stmt.all() as unknown as Record<string, any>[];
  return results.map(row => ({
    ...row,
    timestamp: new Date(row.timestamp)
  }));
}"
}

