  "code": "import { DatabaseSync } from 'node:sqlite';

interface Post {
  id: number;
  title: string;
  content: string;
  status: 'published' | 'draft';
  created_at: Date;
  updated_at: Date;
}

const db = new DatabaseSync(':memory:');
db.exec(`
  CREATE TABLE posts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('published', 'draft')),
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`);

db.exec(`
  CREATE TRIGGER update_timestamp
  AFTER UPDATE ON posts
  FOR EACH ROW
  BEGIN
    UPDATE posts SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
  END;
`);

export const db;

export function getAllPosts(): Post[] {
  const stmt = db.prepare('SELECT * FROM posts');
  return stmt.all() as unknown as Post[];
}

export function getPostById(id: number): Post | null {
  const stmt = db.prepare('SELECT * FROM posts WHERE id = ?');
  return stmt.get([id]) as unknown as Post | null;
}

export function createPost(title: string, content: string, status: 'published' | 'draft'): Post {
  const stmt = db.prepare(
    'INSERT INTO posts (title, content, status) VALUES (?, ?, ?) RETURNING *'
  );
  return stmt.get([title, content, status]) as unknown as Post;
}

export function updatePost(id: number, title: string, content: string, status: 'published' | 'draft'): Post {
  const stmt = db.prepare(
    'UPDATE posts SET title = ?, content = ?, status = ? WHERE id = ? RETURNING *'
  );
  return stmt.get([title, content, status, id]) as unknown as Post;
}

export function deletePost(id: number): void {
  const stmt = db.prepare('DELETE FROM posts WHERE id = ?');
  stmt.run([id]);
}"
}

