{
  "code": "import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is only concerned with DELETE and POST requests
  if (req.method !== 'DELETE' && req.method !== 'POST') {
    return next();
  }

  // Assuming the admin status is stored in req.user.isAdmin
  const isAdmin = req.user?.isAdmin;

  // If the user is not an admin, reject the request
  if (!isAdmin) {
    return res.status(403).json({ message: 'Forbidden: Only admins can perform this action.' });
  }

  // If the user is an admin, allow the request to proceed
  next();
}"
}

