{
  "code": "import React, { FC, useState, useEffect } from 'react';

interface Photo {
  id: number;
  url: string;
  comments: string[];
}

export function PhotoGallery(): FC {
  const [photos, setPhotos] = useState<Photo[]>([]);

  useEffect(() => {
    fetch('/api/photos-api')
      .then(response => response.json())
      .then(data => setPhotos(data));
  }, []);

  const handleComment = (photoId: number, comment: string) => {
    fetch('/api/comment-service', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ photoId, comment })
    });
  };

  const handleDelete = (photoId: number) => {
    fetch('/api/delete-guard', {
      method: 'DELETE',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ photoId })
    }).then(() => {
      setPhotos(photos.filter(photo => photo.id !== photoId));
    });
  };

  return (
    <div>
      {photos.map(photo => (
        <div key={photo.id}>
          <img src={photo.url} alt={`Photo ${photo.id}`} />
          <div>
            {photo.comments.map((comment, index) => (
              <p key={index}>{comment}</p>
            ))}
          </div>
          <input
            type='text'
            placeholder='Add a comment'
            onChange={(e) => handleComment(photo.id, e.target.value)}
          />
          <button onClick={() => handleDelete(photo.id)}>Delete</button>
        </div>
      ))}
    </div>
  );
}"
}

